 import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, SRGBColorSpace, LinearFilter, DoubleSide } from 'three/webgpu';
import { uv, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const colors = config.intent?.visualSpec?.colors ?? {};

  const group = new Group();

  const atlasW = 512;
  const atlasH = 320;
  const aspect = atlasW / atlasH;

  const cardHeight = 1.6;
  const cardWidth = cardHeight * aspect;

  const geometry = new PlaneGeometry(cardWidth, cardHeight, 1, 1);
  const material = new MeshBasicNodeMaterial({ side: DoubleSide });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  let loadedTexture = null;

  mesh.onBeforeRender = function (_renderer, _scene, camera) {
    group.lookAt(camera.position);
  };

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.generateMipmaps = false;
      tex.minFilter = LinearFilter;
      tex.magFilter = LinearFilter;

      loadedTexture = tex;

      material.map = texture(tex, uv());
      material.needsUpdate = true;
    }).catch(() => {});
  } else {
    material.color.set(colors.surface ?? '#0b0b10');
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return group;
}
